        "contentCode": "6.8.1.0",
        "text": "У дівчинки віком 19 років після перенесеної вірусної інфекції протягом трьох днів поступово виникли скарги на труднощі при ходьбі, порушення координації, періодичні падіння. Під час неврологічного огляду виявлено зниження сили з нижніх кінцівок до 4 балів, більше проксимально, сухожилкові рефлекси нижніх кінцівок відсутні, верхніх кінцівок симетрично знижені. Виявлено ознаки атаксії, у позі Ромберга - падіння. При обстеженні черепних нервів - двобічна слабкість m. orbicularis oris, неможливість відведення очних яблук у крайні бокові положення. Який патологічний стан виник у пацієнтки?",
