        "text": "У пацієнта, інфікованого ВІЛ, за останній день виникло 4 генералізованих судомних напади. Після останнього нападу був шпиталізований. Об'єктивно спостерігається: ригідність потиличних м'язів, моторна афазія та правобічний геміпарез. Виконано МРТ головного мозку з контрастним підсиленням, яке виявило кільцеподібні вогнища з перифокальним набряком, які накопичують контраст у вигляді тонкої облямівки. Для якого захворювання характерні ці клініко-лабораторні результати?",
